{
  "technical_and_design_decisions": [
    "Use Spring XD module architecture for source and sink modules, leveraging existing extension points and Java 17.",
    "Use Apache Kafka Java client for source/sink communication and offset management.",
    "Create EC2 AMI using HashiCorp Packer with a base Amazon Linux 2023 image, installing Java 17, Kafka, and performance test tools.",
    "Use GitHub Actions (or equivalent CI) with Windows runners to schedule CI builds and experiment with Windows images to isolate test failures.",
    "Use GitHub Pages with Jekyll for the static site organizing collateral.",
    "For the pluggable SPI POC, define a Service Provider Interface using Java ServiceLoader or Spring dependency injection to enable runtime pluggability.",
    "Performance characterization will use a simple stream (load generator source -> receiving sink) deployed on the created AMI, with throughput measured at the sink."
  ],
  "assumptions": [
    "Existing Spring XD codebase is available and builds on Java 17 as per Spring Framework 6 requirements.",
    "Developer has senior-level experience with Java, Spring, Kafka, AWS, and CI systems.",
    "AWS account and permissions are available to create and test EC2 AMIs.",
    "Windows CI infrastructure (e.g., GitHub Actions or Jenkins) is accessible and remaining test failures are primarily environmental.",
    "Kafka can be run on the AMI (either embedded or as a service) for performance tests.",
    "The Lattice/Diego POC is a research/design task; no production-grade implementation is required in this increment.",
    "Effort estimates are in work-hours for a single developer and exclude unrelated meetings, support, and calendar delays.",
    "Static gh_pages site will be minimal but functional, focusing on links, benchmarks, and reference material."
  ],
  "activities": [
    {
      "activity_id": "ACT-01",
      "activity_name": "Requirements analysis and technical design",
      "activity_description": "Review user stories U1-U8, define technical approach, select tools (Packer, GitHub Actions, Jekyll, etc.), and produce WBS.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "ACT-02",
      "activity_name": "Create EC2 AMI for Kafka performance tests",
      "activity_description": "Automate creation of EC2 AMI with Java 17, Kafka, and perf test tools using Packer; validate by launching instance.",
      "most_likely_effort": 14
    },
    {
      "activity_id": "ACT-03",
      "activity_name": "Implement load generator source module",
      "activity_description": "Develop Spring XD source module that generates synthetic load for performance testing, with configuration and unit tests.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "ACT-04",
      "activity_name": "Implement load receiving sink module",
      "activity_description": "Develop Spring XD sink module that consumes messages and measures received throughput, with configuration and unit tests.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-05",
      "activity_name": "Fix offset management in Kafka source module",
      "activity_description": "Investigate and fix offset handling in existing Kafka source module to efficiently fetch from given offsets; add tests.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-06",
      "activity_name": "Schedule Windows CI builds and stabilize infrastructure",
      "activity_description": "Configure Windows CI pipeline, analyze remaining test failures, experiment with new AMI images, and achieve stable builds for XD runtime.",
      "most_likely_effort": 28
    },
    {
      "activity_id": "ACT-07",
      "activity_name": "Measure performance numbers for a simple stream",
      "activity_description": "Compose a simple stream using source and sink modules, deploy on AMI, run performance tests, and characterize overall throughput.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-08",
      "activity_name": "Create static gh_pages site for collateral",
      "activity_description": "Build GitHub Pages site organizing samples, tutorials, links, performance benchmarks, and reference architectures.",
      "most_likely_effort": 14
    },
    {
      "activity_id": "ACT-09",
      "activity_name": "Continue Lattice/Diego POC for pluggable SPI",
      "activity_description": "Research Lattice/Diego, prototype pluggable SPI in XD runtime, and document scope, risks, and overall design.",
      "most_likely_effort": 36
    },
    {
      "activity_id": "ACT-10",
      "activity_name": "Integration, documentation, and final verification",
      "activity_description": "Integrate all modules, ensure CI passes, write developer documentation, and perform final end-to-end verification.",
      "most_likely_effort": 10
    }
  ],
  "reported_total": {
    "most_likely_effort": 180
  }
}

